const uploadedFiles = [ { name: 'foto.jpg', sizeKB: 120 }, { name: 'shell.php', sizeKB: 5 }, { name: 'cat.jpeg.php', sizeKB: 1 }, { name: 'gambar.png', sizeKB: 900 } ];

function isAllowed(file) {
  const allowedExt = ['.jpg', '.jpeg', '.png', '.gif'];
  const ext = file.name.toLowerCase().includes('.') ? file.name.toLowerCase().slice(file.name.toLowerCase().lastIndexOf('.')) : '';
  const maxKB = 512;
  if (file.sizeKB > maxKB) return false;
  if (!allowedExt.includes(ext)) return false;
  // Tolak pola ganda yang sering dipakai menyamarkan ekstensi
  if (file.name.toLowerCase().includes('.php')) return false;
  return true;
}

for (const f of uploadedFiles) {
  const verdict = isAllowed(f) ? 'ACCEPTED' : 'REJECTED';
  console.log(`${verdict}: ${f.name} (${f.sizeKB}KB)`);
}

const validationPasses = false; // coba true/false
const hasWebExecution = true;  // asumsi file bisa dieksekusi oleh web server

function simulateArbitraryUpload() {
  console.log('Stage 1: Upload request received');
  if (!validationPasses) {
    console.log('Stage 2: Validation failed -> file is blocked');
    console.log('Outcome: No RCE');
    return;
  }

  console.log('Stage 2: Validation passed -> risky file stored');
  if (hasWebExecution) {
    console.log('Stage 3: Web server executes uploaded script -> RCE');
    console.log('Outcome: Server control compromised');
  } else {
    console.log('Stage 3: File stored but not executable -> limited impact');
    console.log('Outcome: No RCE (yet)');
  }
}

simulateArbitraryUpload();
